import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.DBU8LMUS.js";const g=JSON.parse('{"title":"Direktori Alumni","description":"","frontmatter":{"title":"Direktori Alumni","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/direktori.md","filePath":"latest/direktori.md","lastUpdated":1786334463000}'),r={name:"latest/direktori.md"};function l(o,a,k,u,d,s){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="direktori-alumni" tabindex="-1">Direktori Alumni <a class="header-anchor" href="#direktori-alumni" aria-label="Permalink to &quot;Direktori Alumni&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Direktori Alumni</strong> menampilkan daftar alumni ILUNI FT ELEKTRO UNPAK dalam bentuk kartu yang dapat dicari dan disaring. Modul ini menjelaskan cara mencari alumni, menggunakan filter, dan menavigasi hasil pencarian.</p><h2 id="membuka-direktori" tabindex="-1">Membuka Direktori <a class="header-anchor" href="#membuka-direktori" aria-label="Permalink to &quot;Membuka Direktori&quot;">​</a></h2><ol><li>Klik menu <strong>Direktori</strong> pada navigasi.</li><li>Halaman direktori menampilkan kartu-kartu alumni dengan informasi ringkas: nama, angkatan, pekerjaan, perusahaan, dan status <strong>Open to Work</strong> (jika diaktifkan).</li></ol><h2 id="mencari-alumni" tabindex="-1">Mencari Alumni <a class="header-anchor" href="#mencari-alumni" aria-label="Permalink to &quot;Mencari Alumni&quot;">​</a></h2><h3 id="mencari-berdasarkan-nama" tabindex="-1">Mencari Berdasarkan Nama <a class="header-anchor" href="#mencari-berdasarkan-nama" aria-label="Permalink to &quot;Mencari Berdasarkan Nama&quot;">​</a></h3><ol><li>Ketik nama alumni pada kolom <strong>Cari</strong> di bagian atas halaman.</li><li>Hasil pencarian diperbarui secara otomatis menampilkan alumni yang namanya cocok.</li></ol><h3 id="mencari-dengan-kata-kunci-lain" tabindex="-1">Mencari dengan Kata Kunci Lain <a class="header-anchor" href="#mencari-dengan-kata-kunci-lain" aria-label="Permalink to &quot;Mencari dengan Kata Kunci Lain&quot;">​</a></h3><p>Kolom pencarian juga mencocokkan kata kunci dengan:</p><ul><li><strong>Angkatan</strong> (misalnya <code>2015</code>).</li><li><strong>Pekerjaan</strong> (misalnya <code>Engineer</code>).</li><li><strong>Perusahaan</strong> (misalnya <code>PLN</code>).</li><li><strong>Keahlian</strong> (misalnya <code>Python</code>).</li></ul><h2 id="menggunakan-filter" tabindex="-1">Menggunakan Filter <a class="header-anchor" href="#menggunakan-filter" aria-label="Permalink to &quot;Menggunakan Filter&quot;">​</a></h2><p>Halaman direktori menyediakan filter untuk mempersempit hasil:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Fungsi</th></tr></thead><tbody><tr><td><strong>Angkatan</strong></td><td>Menampilkan alumni dari tahun angkatan tertentu.</td></tr><tr><td><strong>Pekerjaan</strong></td><td>Menyaring berdasarkan jabatan atau profesi.</td></tr><tr><td><strong>Perusahaan</strong></td><td>Menyaring berdasarkan tempat bekerja.</td></tr><tr><td><strong>Keahlian</strong></td><td>Menampilkan alumni yang memiliki keahlian tertentu.</td></tr></tbody></table><h3 id="cara-menggunakan-filter" tabindex="-1">Cara Menggunakan Filter <a class="header-anchor" href="#cara-menggunakan-filter" aria-label="Permalink to &quot;Cara Menggunakan Filter&quot;">​</a></h3><ol><li>Klik dropdown filter yang diinginkan.</li><li>Pilih nilai yang sesuai (misalnya angkatan <code>2015</code>).</li><li>Daftar alumni akan diperbarui sesuai kombinasi filter yang aktif.</li><li>Untuk menghapus filter, klik tombol <strong>Hapus Filter</strong> atau atur kembali ke nilai kosong.</li></ol><h2 id="navigasi-halaman-pagination" tabindex="-1">Navigasi Halaman (Pagination) <a class="header-anchor" href="#navigasi-halaman-pagination" aria-label="Permalink to &quot;Navigasi Halaman (Pagination)&quot;">​</a></h2><p>Direktori menampilkan <strong>12 alumni per halaman</strong>. Jika jumlah hasil melebihi 12, gunakan kontrol navigasi di bagian bawah:</p><ol><li>Klik nomor halaman untuk berpindah langsung.</li><li>Gunakan tombol <strong>Sebelumnya</strong> dan <strong>Berikutnya</strong> untuk berpindah satu per satu.</li><li>Informasi jumlah hasil total ditampilkan di sekitar kontrol navigasi.</li></ol><h2 id="membuka-profil-alumni" tabindex="-1">Membuka Profil Alumni <a class="header-anchor" href="#membuka-profil-alumni" aria-label="Permalink to &quot;Membuka Profil Alumni&quot;">​</a></h2><ol><li>Pada hasil pencarian, klik kartu alumni atau tombol <strong>Lihat Profil</strong>.</li><li>Halaman profil alumni akan terbuka menampilkan detail lengkap.</li><li>Gunakan tombol kembali di peramban untuk kembali ke daftar.</li></ol><h2 id="tips-pencarian-efektif" tabindex="-1">Tips Pencarian Efektif <a class="header-anchor" href="#tips-pencarian-efektif" aria-label="Permalink to &quot;Tips Pencarian Efektif&quot;">​</a></h2><ul><li>Gunakan kata kunci yang lebih spesifik, misalnya <code>Electrical Engineer</code> dibanding <code>Engineer</code>.</li><li>Kombinasikan pencarian dan filter untuk hasil paling akurat.</li><li>Perhatikan indikator <strong>Open to Work</strong> pada kartu untuk menemukan alumni yang terbuka terhadap peluang kerja.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/lowongan">Lowongan Kerja</a> untuk melihat peluang yang tersedia.</p>',24)])])}const h=n(r,[["render",l]]);export{g as __pageData,h as default};
